import { createReadStream, createWriteStream } from "node:fs";
import { mkdir, rm, stat } from "node:fs/promises";
import path from "node:path";
import { Readable, Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import type { ReadableStream as NodeWebReadableStream } from "node:stream/web";
import { env } from "../config/env";

/**
 * File storage under FILES_DIR. The directory is never served directly:
 * every read goes through a route handler that checks permissions.
 * Storage keys are generated by the server (UUIDs), never taken from user input.
 */
export class UploadTooLargeError extends Error {
  constructor() {
    super("Upload exceeds the configured size limit");
    this.name = "UploadTooLargeError";
  }
}

export function storageRoot(): string {
  return path.resolve(env().FILES_DIR);
}

/** Resolves a storage key to an absolute path, refusing anything outside the storage root. */
export function resolveStoragePath(key: string, root: string = storageRoot()): string {
  const base = path.resolve(root);
  const full = path.resolve(base, key);
  if (key.includes("\0") || !full.startsWith(base + path.sep)) {
    throw new Error("Invalid storage key");
  }
  return full;
}

export function courseDirKey(courseId: string): string {
  return path.posix.join("courses", courseId);
}

export function courseFileKey(courseId: string, fileId: string): string {
  return path.posix.join(courseDirKey(courseId), "files", fileId);
}

/**
 * Streams an upload to disk without buffering it in memory.
 * Aborts and removes the partial file as soon as `maxBytes` is exceeded.
 * Returns the number of bytes written.
 */
export async function writeUpload(
  key: string,
  body: ReadableStream<Uint8Array>,
  maxBytes: number,
  root: string = storageRoot(),
): Promise<number> {
  const target = resolveStoragePath(key, root);
  await mkdir(path.dirname(target), { recursive: true });

  let size = 0;
  const limiter = new Transform({
    transform(chunk: Buffer, _encoding, callback) {
      size += chunk.length;
      if (size > maxBytes) callback(new UploadTooLargeError());
      else callback(null, chunk);
    },
  });

  try {
    await pipeline(
      Readable.fromWeb(body as unknown as NodeWebReadableStream<Uint8Array>),
      limiter,
      // "wx": never overwrite an existing file.
      createWriteStream(target, { flags: "wx" }),
    );
  } catch (error) {
    await rm(target, { force: true });
    throw error;
  }
  return size;
}

/** Removes a stored file or directory. Missing paths are ignored. */
export async function deleteStored(key: string, root: string = storageRoot()): Promise<void> {
  await rm(resolveStoragePath(key, root), { force: true, recursive: true });
}

/** Opens a stored file for streaming; returns null when it is missing on disk. */
export async function openStored(key: string, root: string = storageRoot()) {
  const target = resolveStoragePath(key, root);
  const info = await stat(target).catch(() => null);
  if (!info?.isFile()) return null;
  return {
    size: info.size,
    stream: Readable.toWeb(createReadStream(target)) as unknown as ReadableStream<Uint8Array>,
  };
}

/** Keeps a user-supplied file name safe to store and to send back in a header. */
export function sanitizeFileName(name: string): string {
  const cleaned = name
    .replace(/[\u0000-\u001f\u007f]/g, "")
    .replace(/[/\\]/g, "_")
    .trim()
    .slice(0, 200);
  return cleaned === "" || cleaned === "." || cleaned === ".." ? "file" : cleaned;
}
